// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 seed) public {
        // Deploy a contract-coded oracle address (initialize validates it via isContract).
        FakeOracle oracle = new FakeOracle(seed);

        // Build ProductInfo calldata raw (name, symbol, payoffDefinition, oracle, params...).
        bytes memory data = abi.encodeWithSelector(
            bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))")),
            "N",
            "S",
            (uint8(0), uint8(1), bytes30(uint248(1) == 0 ? 1 : 1)),
            address(oracle),
            uint256(1e18),
            uint256(0),
            uint256(0),
            uint256(0),
            uint256(0),
            uint256(1000e18),
            (int128(0), int128(1e18), int128(5e17), uint128(8e17))
        );

        // The test contract (has code) acts as controller = msg.sender.
        (bool ok, ) = address(c).call(data);
        if (!ok) return; // admissibility: initialization must succeed

        // General rule: oracle() returns the configured oracle address (a real contract),
        // never the zero address chosen unilaterally.
        assertTrue(
            address(c.oracle()) == address(oracle) && address(c.oracle()).code.length > 0,
            "oracle() must return the configured oracle contract"
        );
    }
}

contract FakeOracle {
    uint256 public immutable seed;
    constructor(uint256 s) { seed = s; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {
    C,
    IProduct,
    IOracleProvider,
    PayoffDefinition,
    PayoffDefinitionLib,
    JumpRateUtilizationCurve,
    PackedFixed18,
    PackedUFixed18,
    UFixed18
} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    OracleStub stub;

    function setUp() public {
        c = new C();
        stub = new OracleStub();
    }

    function testFuzz_property(
        uint8 payoffType,
        uint8 payoffDirection,
        bytes30 data,
        string calldata name,
        string calldata symbol
    ) public {
        PayoffDefinition memory pd = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(payoffType),
            PayoffDefinitionLib.PayoffDirection(payoffDirection),
            data
        );

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name,
            symbol: symbol,
            payoffDefinition: pd,
            oracle: IOracleProvider(address(stub)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e30),
            utilizationCurve: JumpRateUtilizationCurve(
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedUFixed18.wrap(0)
            )
        });

        // The test contract (with code) acts as the controller/mmsg.sender.
        // If this fuzzed payoff definition is inadmissible, initialization
        // reverts and there is nothing to check for that input.
        try c.initialize(info) {
            // General rule: after a successful initialization, c's public
            // oracle() getter must return the configured, code-bearing oracle
            // contract (address(stub)), never some other address.
            assertTrue(
                address(c.oracle()) == address(stub) &&
                    address(c.oracle()).code.length > 0,
                "oracle() must return the configured contract oracle"
            );
        } catch {
            return;
        }
    }
}

contract OracleStub {
    // Exists purely to be a code-bearing address accepted by c's oracle
    // validation; its behavior is irrelevant to the asserted property.
    function ping() external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(bytes30 data, string calldata name_, string calldata symbol_, uint256 seed) public {
        // Keep strings in an admissible (reasonably short) domain
        vm.assume(bytes(name_).length < 64);
        vm.assume(bytes(symbol_).length < 64);

        // Build an admissible product configuration: Linear long payoff, benign params.
        // (Enum values are fixed because out-of-range enum casts panic even in the reference;
        //  the fuzzed inputs are the payoff data and the name/symbol.)
        PayoffDefinition memory payoff = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.Linear,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.Long,
            data: data
        });

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name_,
            symbol: symbol_,
            payoffDefinition: payoff,
            oracle: IOracleProvider(address(new OracleStub())),
            maintenance: UFixed18.wrap(seed % 1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: curve
        });

        c.initialize(info);

        // General rule: a successfully initialized product always exposes the configured
        // code-bearing oracle through its public oracle() getter — never the zero address.
        assertTrue(address(c.oracle()) != address(0));
    }
}

contract OracleStub {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
}

