pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 config) public {
        // derive a wide admissible configuration from the fuzzed input
        PayoffDefinitionLib.PayoffType pType = PayoffDefinitionLib.PayoffType(bound(config % 8, 1, 7));
        PayoffDefinitionLib.PayoffDirection pDir = PayoffDefinitionLib.PayoffDirection((config / 8) % 4);
        bytes30 pData = bytes30(uint240(config));

        ControllerLike controller = new ControllerLike();
        OracleLike oracle = new OracleLike();

        IProduct.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition({
            payoffType: pType,
            payoffDirection: pDir,
            data: pData
        });
        info.oracle = IOracleProvider(address(oracle));
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(int128(1e18)),
            targetRate: PackedFixed18.wrap(int128(5e17)),
            targetUtilization: PackedUFixed18.wrap(uint128(5e17))
        });

        vm.prank(address(controller));
        bool initialized = true;
        try c.initialize(info) {} catch { initialized = false; }
        vm.assume(initialized);

        // GENERAL RULE: for any successfully initialized product, the public
        // oracle() getter exposes the configured, code-bearing oracle contract
        // and never the zero address.
        assertTrue(IOracleProvider.unwrap(c.oracle()) != address(0));
    }
}

