// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // keep the domain wide; enums are small so bound to a few values
        payoffType = uint8(bound(payoffType, 0, 2));
        payoffDirection = uint8(bound(payoffDirection, 0, 1));

        // adversarial counterparties: initialize() requires the caller to be a
        // contract (controller) and the oracle to be a contract address.
        ContractWithCode controller = new ContractWithCode();
        OracleStub oracle = new OracleStub();

        IProduct.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        PayoffDefinition memory pd;
        pd.payoffType = PayoffDefinitionLib.PayoffType(payoffType);
        pd.payoffDirection = PayoffDefinitionLib.PayoffDirection(payoffDirection);
        pd.data = data;
        info.payoffDefinition = pd;
        info.oracle = IOracleProvider(address(oracle));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        vm.prank(address(controller));
        try c.initialize(info) {
            // Rule: the public getter must reflect the stored payoff definition
            // that was set at initialization, for ANY admissible input.
            PayoffDefinition memory got = c.payoffDefinition();
            assertTrue(
                uint8(got.payoffType) == payoffType &&
                uint8(got.payoffDirection) == payoffDirection &&
                got.data == data
            );
        } catch {
            // if this particular combination is not an admissible definition,
            // the property is vacuously satisfied — skip.
            assertTrue(true);
        }
    }
}

